SELECT COUNT(DISTINCT "Uberlandia_1"."Calculation_838513981462429699") AS "ctd_Calculation_838513981462429699_ok",   CAST(EXTRACT(YEAR FROM "Uberlandia_1"."data_de_inicio") AS BIGINT) AS "yr_data_de_inicio_ok" FROM "Uberlandia_1" WHERE ((CAST(EXTRACT(YEAR FROM "Uberlandia_1"."data_de_inicio") AS BIGINT) = 2015) AND (NOT (("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" IN ('CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'Não Matriculado', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR ("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("Uberlandia_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY "yr_data_de_inicio_ok";
